"""YAML renderer – standard library only (no PyYAML dependency)."""

from plugins import PluginError, Renderer, register


def _yaml_value(value) -> str:
    """Return a YAML scalar string for *value*."""
    if value is None:
        return "null"
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, int):
        return str(value)
    if isinstance(value, float):
        return str(value)
    if isinstance(value, str):
        # Quote if the value could be misinterpreted or is empty
        if value == "" or value in ("true", "false", "null", "yes", "no",
                                     "on", "off", "True", "False", "Null",
                                     "Yes", "No", "On", "Off",
                                     "~", "y", "Y", "n", "N"):
            return f"'{value}'"
        # Quote strings that look like numbers
        try:
            float(value)
            return f"'{value}'"
        except ValueError:
            pass
        # Quote strings with special characters
        if any(c in value for c in (":", "{", "}", "[", "]", ",", "&", "*",
                                     "#", "?", "|", "-", "<", ">", "=",
                                     "!", "%", "@", "`", "\\", "\n")):
            return f"'{value}'"
        return value
    if isinstance(value, list):
        items = [_yaml_value(v) for v in value]
        return "[" + ", ".join(items) + "]"
    return str(value)


def _yaml_dump(rows: list[dict]) -> str:
    """Dump a list of flat dicts into a YAML string."""
    if not rows:
        return "[]"
    keys = list(rows[0])
    lines: list[str] = []
    for row in rows:
        lines.append("-")
        for key in keys:
            val = row.get(key)
            lines.append(f"  {key}: {_yaml_value(val)}")
    return "\n".join(lines) + "\n"


@register("yaml")
class YamlRenderer(Renderer):
    def render(self, rows: list[dict]) -> str:
        if not isinstance(rows, list) or not rows:
            raise PluginError("yaml needs a non-empty list of dicts")
        if not all(isinstance(r, dict) for r in rows):
            raise PluginError("yaml needs a non-empty list of dicts")
        return _yaml_dump(rows)

