"""YAML renderer -- standard library only."""

from plugins import PluginError, Renderer, register


def _yaml_scalar(value) -> str:
    """Return a YAML-safe scalar string for *value*."""
    if value is None:
        return "null"
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, int):
        return str(value)
    if isinstance(value, float):
        return str(value)
    # str -- quote if it looks like a special YAML value or contains
    # characters that would confuse a parser.
    s = str(value)
    if s == "":
        return "''"
    # Quote strings that could be misinterpreted as non-strings.
    if s.lower() in (
        "true", "false", "yes", "no", "on", "off",
        "null", "~",
        "null", "Null", "NULL",
        ".inf", "-.inf", ".nan",
    ):
        return f"'{s}'"
    # Quote if it starts/ends with whitespace, or contains special chars.
    if (
        s[0] in (' ', '\t')
        or s[-1] in (' ', '\t')
        or any(c in s for c in (':', '{', '}', '[', ']', ',', '&', '*', '?', '|', '-', '<', '>', '=', '!', '%', '@', '`'))
    ):
        return f"'{s}'"
    return s


def _yaml_dump_rows(rows: list[dict]) -> str:
    """Dump *rows* (list of flat dicts) into a YAML string."""
    keys = list(rows[0])
    lines: list[str] = []
    for row in rows:
        lines.append("-")
        for k in keys:
            lines.append(f"  {k}: {_yaml_scalar(row[k])}")
    return "\n".join(lines) + "\n"


@register("yaml")
class YamlRenderer(Renderer):
    def render(self, rows: list[dict]) -> str:
        if not isinstance(rows, list) or not rows:
            raise PluginError("yaml needs a non-empty list of dicts")
        if not all(isinstance(r, dict) for r in rows):
            raise PluginError("yaml needs a non-empty list of dicts")
        return _yaml_dump_rows(rows)

